        return uint256(vm.load(address(token), key));
    }

    // Finds a base slot where BOTH accounts flipped 0 -> nonzero.
    function _findCommonChangedSlot(
        uint256[] memory b1,
        uint256[] memory a1,
        uint256[] memory b2,
